// ===== Odin 0.4: leveled passages for comprehension sheets (written for Odin; fables are public-domain stories retold) =====
// g: level group. k1 = kindergarten and grade 1 (the teacher reads the passage aloud, 3 choices), 2, 3, 45 = grades 4 and 5.
// Each question: [question, answer, [wrong answers], tag, why]. Tags match the benchmark concepts so sheets can lean
// toward what a student missed (theme, point of view, central idea, structure, figurative language ...).
const SH_PASSAGES = [
  // ---------------- literature, K-1 ----------------
  { id: "L1a", skill: "LIT", g: "k1", title: "The Lost Mitten", text: "Pam had a red mitten. She lost it in the snow. She looked by the tree. She looked by the swing. Her dog Max dug in the snow. Max found the mitten! Pam gave Max a big hug.",
    qs: [["Who lost a mitten?", "Pam", ["Max", "Mom"], "elements", "The story says Pam lost her red mitten."], ["Where did Pam lose the mitten?", "in the snow", ["at school", "in the bath"], "elements", "She lost it in the snow."],
         ["Who found the mitten?", "Max the dog", ["Pam", "a cat"], "elements", "Max dug in the snow and found it."], ["How did Pam feel at the end?", "happy", ["sad", "mad"], "retell", "She gave Max a big hug, so she was happy."]] },
  { id: "L1b", skill: "LIT", g: "k1", title: "Ben Plants a Seed", text: "Ben put a seed in a pot. He gave it water every day. He put it in the sun. One day, he saw a little green leaf. Ben smiled. Soon a big yellow flower grew.",
    qs: [["What did Ben put in the pot?", "a seed", ["a rock", "a toy"], "elements", "Ben put a seed in a pot."], ["What did Ben do every day?", "gave it water", ["sang to it", "dug a hole"], "elements", "He gave it water every day."],
         ["What happened first?", "Ben put a seed in a pot", ["a flower grew", "Ben saw a leaf"], "retell", "The story starts with Ben planting the seed."], ["What grew at the end?", "a yellow flower", ["a tree", "a carrot"], "retell", "Soon a big yellow flower grew."]] },
  { id: "L1c", skill: "LIT", g: "k1", title: "Kim and the Kite", text: "Kim had a new kite. The wind was strong. Up, up went the kite! Then the string broke. The kite got stuck in a tree. Dad got a ladder and got it down. Kim said, \"Thank you, Dad!\"",
    qs: [["What did Kim have?", "a kite", ["a ball", "a bike"], "elements", "Kim had a new kite."], ["What was the problem?", "the kite got stuck in a tree", ["Kim was hungry", "it rained"], "elements", "The string broke and the kite got stuck in a tree."],
         ["How was the problem solved?", "Dad used a ladder", ["Kim cried", "the wind stopped"], "elements", "Dad got a ladder and got it down."], ["What did Kim say to Dad?", "Thank you", ["Go away", "Good night"], "retell", "Kim said, \"Thank you, Dad!\""]] },
  { id: "L1d", skill: "LIT", g: "k1", title: "The Big Race", text: "Turtle and Rabbit had a race. Rabbit ran fast. Then Rabbit took a nap. Turtle went slow, but she did not stop. Turtle won the race!",
    qs: [["Who ran fast?", "Rabbit", ["Turtle", "a dog"], "elements", "Rabbit ran fast."], ["What did Rabbit do in the middle of the race?", "took a nap", ["ate lunch", "went swimming"], "retell", "Then Rabbit took a nap."],
         ["Who won the race?", "Turtle", ["Rabbit", "nobody"], "retell", "Turtle won the race!"], ["What is the lesson?", "keep going and do not give up", ["always run fast", "naps are fun"], "theme", "Turtle was slow but kept going, and she won."]] },
  // ---------------- informational, K-1 ----------------
  { id: "I1a", skill: "INF", g: "k1", title: "Frogs", text: "A frog starts as an egg in a pond. The egg hatches into a tadpole. A tadpole has a tail and swims. Then it grows legs. Its tail gets smaller. Now it is a frog! Frogs can hop and swim.",
    qs: [["What is this mostly about?", "how a frog grows", ["how to swim", "a pond party"], "central", "Every part tells how a frog grows from an egg."], ["What hatches from the egg?", "a tadpole", ["a fish", "a bird"], "central", "The egg hatches into a tadpole."],
         ["What does a tadpole have?", "a tail", ["wings", "fur"], "features", "A tadpole has a tail and swims."], ["What can frogs do?", "hop and swim", ["fly", "bark"], "central", "Frogs can hop and swim."]] },
  { id: "I1b", skill: "INF", g: "k1", title: "Fire Trucks", text: "A fire truck is big and red. It has a long ladder. It has a hose to spray water. Firefighters ride on the truck. When there is a fire, the truck goes fast. Its siren is loud so cars move out of the way.",
    qs: [["What is this mostly about?", "fire trucks", ["ice cream trucks", "dogs"], "central", "Every sentence tells about fire trucks."], ["What does the hose do?", "sprays water", ["plays music", "holds food"], "central", "It has a hose to spray water."],
         ["Why is the siren loud?", "so cars move out of the way", ["so people sing", "to wake the firefighters"], "purpose", "Its siren is loud so cars move out of the way."], ["Who rides on the truck?", "firefighters", ["farmers", "teachers"], "central", "Firefighters ride on the truck."]] },
  { id: "I1c", skill: "INF", g: "k1", title: "Sea Turtles", text: "Sea turtles live in the ocean. Mother sea turtles come to the beach at night. They dig a hole in the sand and lay eggs. The baby turtles hatch and walk to the water. In Florida, people turn off beach lights to help the babies find the sea.",
    qs: [["Where do sea turtles live?", "in the ocean", ["in a tree", "in a desert"], "central", "Sea turtles live in the ocean."], ["Where do mother turtles lay eggs?", "in the sand", ["in a tree", "in the water"], "central", "They dig a hole in the sand and lay eggs."],
         ["Why do people turn off beach lights?", "to help baby turtles find the sea", ["to go to sleep", "to save money"], "purpose", "The lights are turned off to help the babies find the sea."], ["What is this mostly about?", "sea turtles", ["beach toys", "fish"], "central", "The whole text is about sea turtles."]] },
  { id: "I1d", skill: "INF", g: "k1", title: "Our Five Senses", text: "We have five senses. We see with our eyes. We hear with our ears. We smell with our nose. We taste with our tongue. We touch with our skin. Our senses help us learn about the world.",
    qs: [["How many senses do we have?", "five", ["two", "ten"], "central", "We have five senses."], ["What do we hear with?", "our ears", ["our eyes", "our nose"], "central", "We hear with our ears."],
         ["What do we taste with?", "our tongue", ["our hands", "our feet"], "central", "We taste with our tongue."], ["What is this mostly about?", "our five senses", ["our toys", "our pets"], "central", "It tells about our five senses."]] },
  // ---------------- literature, grade 2 ----------------
  { id: "L2a", skill: "LIT", g: "2", title: "The Class Garden", text: "Ms. Lee's class planted a garden behind the school. Diego wanted to plant only carrots, because carrots were his favorite. Ava wanted only sunflowers. They argued until nothing got planted at all. Ms. Lee asked, \"What if the garden had both?\" Diego and Ava made a plan together. Diego dug the rows, and Ava watered every morning. By spring, the garden had tall sunflowers and orange carrots. Diego said, \"Our garden is better because we worked together.\"",
    qs: [["What was the problem at first?", "Diego and Ava could not agree on what to plant", ["it did not rain", "the garden had bugs", "Ms. Lee was sick"], "elements", "They argued until nothing got planted."],
         ["How did they solve the problem?", "they planted both carrots and sunflowers", ["they planted only carrots", "they asked another class", "they gave up"], "elements", "They made a plan to plant both."],
         ["What lesson does the story teach?", "working together can make things better", ["carrots are the best food", "always plant sunflowers", "gardens need lots of rain"], "theme", "Diego says the garden is better because they worked together."],
         ["What happened right after Ms. Lee asked her question?", "Diego and Ava made a plan", ["the sunflowers grew", "they argued", "spring came"], "retell", "The next sentence says they made a plan together."],
         ["How did Diego feel at the end?", "proud of their teamwork", ["angry at Ava", "bored", "sad about the carrots"], "elements", "He says their garden is better because they worked together."]] },
  { id: "L2b", skill: "LIT", g: "2", title: "Rosa's Brave Day", text: "Rosa was nervous about the swimming test. The pool looked deep, and her stomach felt full of butterflies. Her coach said, \"Take a deep breath and kick like we practiced.\" Rosa jumped in. She kicked and kicked until she touched the wall. Everyone clapped. Rosa grinned. \"I was scared,\" she said, \"but I did it anyway.\"",
    qs: [["How did Rosa feel before the test?", "nervous", ["sleepy", "angry", "bored"], "elements", "The story says Rosa was nervous."],
         ["What does \"her stomach felt full of butterflies\" mean?", "she felt nervous", ["she ate butterflies", "she was hungry", "she saw butterflies"], "figurative", "It is a way to say she felt nervous."],
         ["What did the coach tell Rosa to do?", "take a deep breath and kick", ["go home", "swim slowly", "stop practicing"], "elements", "The coach said, \"Take a deep breath and kick.\""],
         ["What is the lesson of the story?", "you can be brave even when you feel scared", ["pools are always deep", "coaches are strict", "swimming is easy"], "theme", "Rosa was scared but did it anyway."],
         ["What happened at the end?", "Rosa touched the wall and everyone clapped", ["Rosa quit", "the pool closed", "Rosa lost her goggles"], "retell", "She touched the wall, and everyone clapped."]] },
  { id: "L2c", skill: "LIT", g: "2", title: "The Fox and the Grapes", text: "A hungry fox saw some purple grapes hanging from a vine. \"Those look sweet,\" he said. He jumped, but the grapes were too high. He jumped again and again. At last he walked away with his nose in the air. \"Those grapes are probably sour anyway,\" he grumbled.",
    qs: [["What did the fox want?", "the grapes", ["a nap", "some water", "a friend"], "elements", "He saw the grapes and said they looked sweet."],
         ["Why couldn't the fox get the grapes?", "they were too high", ["they were sour", "a bird ate them", "it was dark"], "elements", "He jumped, but the grapes were too high."],
         ["Why did the fox say the grapes were sour?", "to feel better about not getting them", ["he tasted them", "a friend told him", "they were green"], "elements", "He never tasted them; he said it after he gave up."],
         ["What lesson does the story teach?", "people sometimes pretend they don't want what they can't have", ["always eat grapes", "foxes are fast", "never jump"], "theme", "The fox pretends he didn't want the grapes."],
         ["What does \"grumbled\" mean?", "complained in a grumpy way", ["sang happily", "shouted for help", "whispered a secret"], "context", "He was upset, so he said it in a grumpy way."]] },
  { id: "L2d", skill: "LIT", g: "2", title: "The Missing Lunchbox", text: "Omar could not find his lunchbox. He looked under his desk and in his backpack. \"Maybe someone took it,\" he thought. Then his friend Nia pointed at the windowsill. There it was, next to the class fish tank. Omar laughed. He had put it there when he fed the fish that morning. \"Next time I'll slow down and remember where I put things,\" he said.",
    qs: [["What was Omar's problem?", "he could not find his lunchbox", ["he was late", "he forgot his homework", "the fish was sick"], "elements", "Omar could not find his lunchbox."],
         ["Where was the lunchbox?", "on the windowsill", ["in his backpack", "under his desk", "in the cafeteria"], "elements", "It was on the windowsill next to the fish tank."],
         ["Why was the lunchbox there?", "Omar put it down when he fed the fish", ["Nia hid it", "the teacher moved it", "it fell"], "elements", "He had put it there when he fed the fish."],
         ["Who helped Omar?", "Nia", ["the teacher", "his mom", "the principal"], "elements", "Nia pointed at the windowsill."],
         ["What did Omar learn?", "to slow down and remember where he puts things", ["to buy a new lunchbox", "to never feed the fish", "to blame others"], "theme", "He says he'll slow down next time."]] },
  // ---------------- informational, grade 2 ----------------
  { id: "I2a", skill: "INF", g: "2", title: "How Bees Help Plants", text: "Bees fly from flower to flower to drink a sweet liquid called nectar. While a bee drinks, yellow dust called pollen sticks to its fuzzy body. When the bee visits the next flower, some pollen rubs off. This helps the plant make seeds and fruit. Without bees, we would have fewer apples, berries and pumpkins. That is why some farmers keep beehives near their fields.",
    qs: [["What is the main idea?", "bees help plants make seeds and fruit", ["bees live in hives", "pollen is yellow", "farmers grow pumpkins"], "central", "Most details explain how bees help plants make seeds and fruit."],
         ["What is nectar?", "a sweet liquid in flowers", ["yellow dust", "a kind of seed", "a beehive"], "context", "The text says nectar is a sweet liquid."],
         ["What sticks to a bee's body?", "pollen", ["honey", "water", "leaves"], "central", "Yellow dust called pollen sticks to its body."],
         ["What happens after pollen rubs off on the next flower?", "the plant can make seeds and fruit", ["the bee goes to sleep", "the flower closes", "it rains"], "structure", "This helps the plant make seeds and fruit."],
         ["Why do some farmers keep beehives near their fields?", "so bees help their plants make fruit", ["to scare birds", "to make the fields pretty", "to keep bees warm"], "purpose", "Bees help plants make fruit."]] },
  { id: "I2b", skill: "INF", g: "2", title: "The Everglades", text: "The Everglades is a huge wetland in southern Florida. Slow-moving water flows through tall sawgrass, so people call it a \"river of grass.\" Many animals live there, such as alligators, wading birds and manatees. The Everglades also gives drinking water to millions of people. Because it is so important, much of it is protected as a national park.",
    qs: [["Where are the Everglades?", "in southern Florida", ["in a desert", "on a mountain", "in the ocean"], "central", "It is a wetland in southern Florida."],
         ["Why is it called a \"river of grass\"?", "water flows slowly through tall grass", ["it is made of grass", "grass grows in rivers", "it is green"], "context", "Slow-moving water flows through tall sawgrass."],
         ["Which animal lives there?", "alligators", ["polar bears", "camels", "penguins"], "central", "Alligators, wading birds and manatees live there."],
         ["What is the main idea?", "the Everglades is an important wetland full of life", ["alligators are big", "Florida is hot", "parks are fun"], "central", "The details show it is important and full of life."],
         ["Why is much of it protected?", "because it is so important", ["because it is small", "because no one lives there", "because it is dry"], "structure", "Because it is so important, much of it is protected."]] },
  { id: "I2c", skill: "INF", g: "2", title: "Make Butter in a Jar", text: "You can make butter in a jar! First, pour heavy cream into a clean jar until it is half full. Next, close the lid tightly. Then shake the jar hard for about ten minutes. The cream will get thick, and then a yellow lump will form. That lump is butter! Last, pour off the liquid and spread your butter on bread.",
    qs: [["How is this text organized?", "as steps in order", ["as a story about a family", "as a list of animals", "as a comparison of two foods"], "structure", "First, next, then and last show steps in order."],
         ["What do you do first?", "pour cream into a jar", ["shake the jar", "spread butter on bread", "close the lid"], "structure", "First, pour heavy cream into a clean jar."],
         ["How long should you shake the jar?", "about ten minutes", ["one second", "all day", "two hours"], "central", "Shake the jar hard for about ten minutes."],
         ["What does \"tightly\" tell you?", "close the lid so it is firmly shut", ["leave the lid loose", "open the lid", "paint the lid"], "context", "Tightly means firmly, so no cream spills."],
         ["Why did the author write this?", "to teach how to make butter", ["to tell a funny story", "to sell jars", "to describe cows"], "purpose", "It gives steps for making butter."]] },
  { id: "I2d", skill: "INF", g: "2", title: "Why We Have Day and Night", text: "The Earth is always spinning, like a top. It makes one full spin every 24 hours. When your side of the Earth faces the sun, it is day. When your side turns away from the sun, it is night. So when it is day in Florida, it is night on the other side of the world.",
    qs: [["What is the main idea?", "the Earth's spinning causes day and night", ["the sun moves around us", "Florida is sunny", "tops spin fast"], "central", "The text explains that spinning makes day and night."],
         ["How long does one full spin take?", "24 hours", ["1 hour", "7 days", "1 year"], "central", "It makes one full spin every 24 hours."],
         ["When is it day for you?", "when your side faces the sun", ["when the moon is out", "when you wake up", "when it rains"], "structure", "When your side faces the sun, it is day."],
         ["What causes night?", "your side of the Earth turns away from the sun", ["clouds cover the sun", "the sun turns off", "the moon blocks the sun"], "structure", "When your side turns away from the sun, it is night."],
         ["The author compares the Earth to", "a top", ["a ball", "a clock", "a car"], "features", "The Earth is always spinning, like a top."]] },
  // ---------------- literature, grade 3 ----------------
  { id: "L3a", skill: "LIT", g: "3", title: "The Science Fair", text: "Maya's volcano was supposed to erupt with red foam, but when she poured in the vinegar, nothing happened. Kids at the next table giggled. Maya's face felt hot. She wanted to pack up and go home. Instead, she read her notes again and noticed she had used flour instead of baking soda. Her friend Luis offered her the extra baking soda from his project. Maya tried again, and this time red foam bubbled over the top. The judges smiled and wrote on their clipboards. Maya didn't win a ribbon, but she walked home feeling proud. \"Mistakes are just clues,\" she told her mom.",
    qs: [["What was Maya's problem?", "her volcano did not erupt", ["she lost her notes", "Luis was mean", "the judges left"], "elements", "When she poured in the vinegar, nothing happened."],
         ["Why did the volcano not work at first?", "she used flour instead of baking soda", ["she forgot the vinegar", "it was too cold", "Luis took her baking soda"], "elements", "She noticed she had used flour instead of baking soda."],
         ["\"Maya's face felt hot\" shows that she felt", "embarrassed", ["sick", "sleepy", "happy"], "figurative", "Kids giggled, and her face felt hot: she was embarrassed."],
         ["What is the theme?", "mistakes can help you learn", ["always win a ribbon", "science is easy", "never share supplies"], "theme", "Maya says, \"Mistakes are just clues.\""],
         ["How does Maya change?", "from wanting to quit to feeling proud", ["from proud to sad", "from happy to bored", "she does not change"], "elements", "She wanted to go home, but she ended up proud."]] },
  { id: "L3b", skill: "LIT", g: "3", title: "Grandpa's Boat", text: "Every Saturday, Eli and his grandpa fixed the old boat in the garage. Grandpa showed him how to sand the wood smooth and paint it with care. Eli thought it was taking forever. \"When will we take it to the water?\" he asked each week. \"When it's ready,\" Grandpa said with a wink. Months later, they pushed the boat into the lake. It floated! As they drifted under the bright sky, Eli finally understood. The waiting had made this moment feel even better. He decided to name the boat Patience.",
    qs: [["Who tells this story?", "a narrator who is not in the story", ["Eli", "Grandpa", "the boat"], "pov", "The story says \"he\" and \"Eli,\" not \"I.\""],
         ["How did Eli feel about fixing the boat at first?", "impatient", ["scared", "proud", "angry at Grandpa"], "elements", "He thought it was taking forever and asked every week."],
         ["Why does Eli name the boat Patience?", "he learned that waiting made the moment better", ["it is Grandpa's name", "the boat was slow", "he liked the sound of it"], "elements", "The waiting made the moment feel even better."],
         ["What is the theme?", "good things can be worth waiting for", ["boats are hard to fix", "grandparents know everything", "never paint wood"], "theme", "Eli learns that waiting made the moment better."],
         ["What does \"drifted\" mean?", "moved slowly with the water", ["sank", "raced", "flipped over"], "context", "They floated slowly on the lake."]] },
  { id: "L3c", skill: "LIT", g: "3", title: "Rain Song", poem: true, text: "Tap, tap, tap on the window glass,\nRain is dancing on the grass.\nPuddles grow like mirrors wide,\nClouds are pillows, gray outside.\nWhen the sun comes peeking through,\nEvery leaf is shiny new.",
    qs: [["What does the poet compare puddles to?", "mirrors", ["pillows", "dancers", "windows"], "poetry", "\"Puddles grow like mirrors wide.\""],
         ["Which two words rhyme?", "glass and grass", ["rain and wide", "clouds and new", "tap and sun"], "poetry", "Glass and grass end with the same sounds."],
         ["\"Rain is dancing on the grass\" gives rain", "a human action", ["a color", "a number", "a smell"], "figurative", "Rain can't really dance; this is personification."],
         ["How does the poem end?", "the sun comes out and the leaves look shiny", ["it rains harder", "the puddles freeze", "it snows"], "poetry", "The last two lines describe the sun peeking through."],
         ["What is the poem mostly about?", "a rainy day and the sun that follows", ["a trip to the beach", "a broken window", "a garden party"], "theme", "It describes rain, then the sun coming out."]] },
  { id: "L3d", skill: "LIT", g: "3", title: "The Two Painters", text: "Zoe and Ivy each painted the same tree for an art contest. Zoe painted fast, using bold reds and oranges. Ivy painted slowly, adding every leaf. When they finished, Zoe said, \"Mine looks better because it's brighter.\" Ivy said, \"Mine looks better because it's more real.\" Their teacher hung both paintings side by side. \"Each one shows something the other doesn't,\" she said. Zoe and Ivy looked again and saw that the teacher was right.",
    qs: [["How were the girls' painting styles different?", "Zoe painted fast and bold; Ivy painted slowly with detail", ["both painted fast", "both used only green", "Ivy was bold and Zoe was slow"], "elements", "Zoe painted fast with bold colors; Ivy added every leaf."],
         ["Why did Zoe think her painting was better?", "it was brighter", ["it was more real", "it was bigger", "the teacher said so"], "pov", "Zoe said, \"because it's brighter.\""],
         ["What did the teacher mean?", "each painting shows something special", ["both paintings are bad", "Ivy's is better", "they should paint faster"], "theme", "Each one shows something the other doesn't."],
         ["What is the theme?", "people see things differently, and both views can have value", ["brighter is always better", "art contests are unfair", "trees are hard to paint"], "theme", "Both girls learn that each painting has value."],
         ["What happened at the end?", "the girls agreed with the teacher", ["they stopped being friends", "Zoe won", "they painted again"], "elements", "They saw that the teacher was right."]] },
  // ---------------- informational, grade 3 ----------------
  { id: "I3a", skill: "INF", g: "3", title: "Manatees: Gentle Giants", text: "Manatees are large, slow-moving mammals that live in warm water. In winter, many Florida manatees swim to warm springs and to the warm water near power plants. Manatees eat plants and can munch through about 100 pounds of sea grass in one day. Because they move slowly and stay near the surface, boats can hit them. To protect manatees, some areas have \"slow speed\" zones where boats must go slowly. These rules help keep these gentle giants safe.",
    qs: [["What is the central idea?", "manatees need warm water and protection from boats", ["power plants make electricity", "sea grass is green", "boats are fast"], "central", "Most details are about manatees' needs and safety."],
         ["Why do manatees swim to warm springs in winter?", "to find warm water", ["to find food", "to have babies", "to hide from sharks"], "structure", "They live in warm water, so they move to warm springs."],
         ["How much sea grass can a manatee eat in a day?", "about 100 pounds", ["about 1 pound", "about 1,000 pounds", "none"], "central", "About 100 pounds of sea grass in one day."],
         ["Why can boats hit manatees?", "they move slowly and stay near the surface", ["they swim at night", "they are very small", "they like boats"], "structure", "This is the cause the text gives."],
         ["Why does the author mention \"slow speed\" zones?", "to show one way people protect manatees", ["to explain how boats are built", "to describe the weather", "to sell boats"], "purpose", "The zones protect manatees."]] },
  { id: "I3b", skill: "INF", g: "3", title: "Why Leaves Change Color", text: "Leaves are green because of chlorophyll, which helps plants make food from sunlight. In fall, in many places, days get shorter and cooler. Trees stop making chlorophyll, so the green fades. Then yellow and orange colors that were hiding in the leaves begin to show. Some trees also make new red colors. In south Florida, most trees stay green all year because it stays warm.",
    qs: [["What makes leaves green?", "chlorophyll", ["sunlight", "rain", "soil"], "central", "Leaves are green because of chlorophyll."],
         ["How is most of this text organized?", "cause and effect", ["a story with characters", "steps to make something", "a list of trees by size"], "structure", "It explains what causes the color change."],
         ["What happens when trees stop making chlorophyll?", "the green fades and other colors show", ["leaves grow bigger", "trees make more food", "leaves turn blue"], "structure", "The green fades and yellow and orange show."],
         ["Why do most trees in south Florida stay green?", "it stays warm all year", ["they get no sunlight", "they are painted", "they have no chlorophyll"], "structure", "Because it stays warm."],
         ["What is the central idea?", "leaves change color when trees stop making chlorophyll", ["Florida is warm", "red is a pretty color", "trees need water"], "central", "The details explain why leaves change color."]] },
  { id: "I3c", skill: "INF", g: "3", title: "Our School Needs a Garden", text: "Our school should build a garden. First, a garden would let students learn science by watching seeds grow. Second, students could eat fresh vegetables they grew themselves. Third, working in a garden is good exercise. Some people say a garden costs too much, but many stores donate seeds and tools to schools. A school garden would help us learn, eat well and stay active.",
    qs: [["What is the author's claim?", "our school should build a garden", ["gardens cost too much", "vegetables taste bad", "science is hard"], "argument", "The first sentence states the claim."],
         ["Which is a reason the author gives?", "students could eat fresh vegetables", ["gardens are messy", "stores sell tools", "seeds are tiny"], "argument", "The second reason is fresh vegetables."],
         ["How does the author answer people who say a garden costs too much?", "many stores donate seeds and tools", ["gardens are free", "cost doesn't matter", "parents should pay"], "argument", "Many stores donate seeds and tools to schools."],
         ["Why did the author write this?", "to persuade readers to support a school garden", ["to tell a funny story", "to explain how seeds grow", "to describe vegetables"], "purpose", "The author gives reasons to convince readers."],
         ["The words \"First,\" \"Second\" and \"Third\" help the reader", "follow the reasons in order", ["find the title", "know who is talking", "see a picture"], "structure", "They number the reasons."]] },
  { id: "I3d", skill: "INF", g: "3", title: "From Sand to Glass", text: "Glass is made from sand! First, workers heat sand with a few other materials in a very hot furnace. The heat melts the sand into a glowing, sticky liquid. Next, the liquid is shaped by blowing, pressing or pouring it into molds. As it cools, it becomes hard and clear. Glass can be melted and shaped again and again, so it is easy to recycle.",
    qs: [["How is this text organized?", "as steps in order", ["compare and contrast", "problem and solution", "as a poem"], "structure", "First, next and as it cools show the steps."],
         ["What is glass made from?", "sand", ["wood", "ice", "plastic"], "central", "Glass is made from sand."],
         ["What happens to the sand in the furnace?", "it melts into a liquid", ["it turns to ice", "it becomes wood", "it disappears"], "structure", "The heat melts the sand into a liquid."],
         ["Why is glass easy to recycle?", "it can be melted and shaped again", ["it is heavy", "it is clear", "it breaks"], "structure", "It can be melted and shaped again and again."],
         ["What is a furnace?", "a very hot oven", ["a tool for cutting", "a kind of glass", "a mold"], "context", "Workers heat sand in a very hot furnace."]] },
  // ---------------- literature, grades 4-5 ----------------
  { id: "L4a", skill: "LIT", g: "45", title: "The Map Keeper", text: "When Grandma Rosa moved in with us, she brought a dented metal box. Inside were dozens of hand-drawn maps of places she had lived: a fishing village by the sea, a busy street in Miami, the apartment where Mom grew up. My little brother asked why she didn't just use a phone. Grandma smiled. \"A phone shows you where to go,\" she said. \"These maps show me where I've been.\" That night I couldn't sleep, so I drew a map of our neighborhood: the mango tree, the crooked mailbox, the park where I broke my wrist. At breakfast, I slid it across the table. Grandma studied it for a long time, then placed it carefully in her box. \"Now,\" she said, \"you're part of the story too.\"",
    qs: [["From whose point of view is the story told?", "a grandchild in the family", ["Grandma Rosa", "the little brother", "Mom"], "pov", "The narrator says \"I\" and calls her Grandma."],
         ["What does Grandma mean by \"These maps show me where I've been\"?", "the maps hold her memories", ["she is lost", "phones are broken", "she wants to travel"], "figurative", "Her maps are of places she lived, so they keep her memories."],
         ["Why does the narrator draw a map?", "Grandma's maps inspired them", ["it was homework", "to find the park", "to sell it"], "elements", "After hearing Grandma, the narrator drew their own map."],
         ["What is the theme?", "the places we live hold our family's stories", ["phones are better than maps", "mango trees are tall", "moving is easy"], "theme", "The maps connect places to family stories."],
         ["What does Grandma's final action show?", "she values the map as part of the family story", ["she doesn't like it", "she wants to throw it away", "she is tired"], "elements", "She keeps it and says, \"you're part of the story too.\""]] },
  { id: "L4b", skill: "LIT", g: "45", title: "The Tryout", text: "Kai had practiced free throws every afternoon for a month, but at the basketball tryout his hands shook. He missed his first three shots. Coach Miller wrote something on her clipboard, and Kai was sure it said \"No.\" On the fourth shot, he remembered what his sister told him: \"Breathe, bend, follow through.\" The ball swished through the net. He made the next one, and the next. After tryouts, Coach Miller called him over. \"You missed early,\" she said, \"but you didn't fall apart. That tells me more than a perfect start.\" Kai made the team, but what he remembered most was the moment he decided to keep shooting.",
    qs: [["How does Kai feel at the start of the tryout?", "nervous", ["bored", "angry", "confident"], "elements", "His hands shook."],
         ["What helps Kai turn things around?", "remembering his sister's advice", ["the coach yelling", "a new ball", "taking a break"], "elements", "He remembered, \"Breathe, bend, follow through.\""],
         ["What does the coach value most?", "how Kai handled his mistakes", ["a perfect start", "Kai's height", "his sister's advice"], "pov", "She says not falling apart tells her more than a perfect start."],
         ["What is the theme?", "how you respond to mistakes matters", ["practice is pointless", "coaches are unfair", "basketball is easy"], "theme", "Kai kept going after missing."],
         ["What does \"fall apart\" mean here?", "lose control and give up", ["break into pieces", "fall down", "run away"], "figurative", "Kai didn't give up after missing."]] },
  { id: "L4c", skill: "LIT", g: "45", title: "The Old Oak", poem: true, text: "The old oak stands with arms spread wide,\nA shelter where the sparrows hide.\nThrough summer storms and winter's chill,\nIt holds its ground upon the hill.\nIts roots, like fingers, grip the earth;\nIts rings remember every birth\nOf spring that came, of spring that went—\nA hundred years of time well spent.",
    qs: [["In the poem, \"arms spread wide\" describes", "the tree's branches", ["a person's arms", "the sparrows' wings", "the hill"], "figurative", "The oak's branches are described as arms."],
         ["\"Its roots, like fingers, grip the earth\" is an example of", "a simile", ["a fact", "a question", "a title"], "figurative", "It compares roots to fingers using \"like.\""],
         ["What does the poem suggest about the tree?", "it is strong and has lasted a long time", ["it is young and weak", "it is about to fall", "it has no leaves"], "poetry", "It holds its ground for a hundred years."],
         ["Which pair of words rhymes in the poem?", "chill and hill", ["oak and wide", "roots and earth", "storms and spent"], "poetry", "Chill and hill end with the same sounds."],
         ["What is the theme of the poem?", "strength and endurance over time", ["trees are scary", "winter is cold", "birds are noisy"], "theme", "The oak lasts through storms for a hundred years."]] },
  { id: "L4d", skill: "LIT", g: "45", title: "Two Sides of the Fence", text: "The Garcias wanted to plant a row of tall bushes along the fence for privacy. Their neighbor, Mr. Bell, had grown sunflowers on his side of the fence for twenty years, and the bushes would block their sunlight. At first, both families were annoyed. Mr. Bell said the Garcias didn't care about his flowers. Mrs. Garcia said Mr. Bell didn't respect their need for privacy. Then nine-year-old Lucia had an idea: what if they planted shorter bushes at the sunny end and taller ones at the shady end? The adults measured, argued a little more, and finally agreed. By summer, the sunflowers were taller than ever, and Lucia's family had their privacy.",
    qs: [["What was the conflict?", "the bushes would block the sunflowers' sunlight", ["the fence was broken", "the sunflowers died", "a dog dug holes"], "elements", "Tall bushes would block the sunflowers' sun."],
         ["How did Mr. Bell see the problem?", "the Garcias didn't care about his flowers", ["he wanted privacy", "he wanted more bushes", "he wanted to move"], "pov", "Mr. Bell said the Garcias didn't care about his flowers."],
         ["How was the conflict solved?", "Lucia's plan of short and tall bushes", ["they removed the fence", "Mr. Bell moved away", "they gave up"], "elements", "Shorter bushes at the sunny end, taller at the shady end."],
         ["What is the theme?", "creative solutions can meet everyone's needs", ["neighbors always argue", "sunflowers need shade", "children should stay out of adult problems"], "theme", "Lucia's idea worked for both families."],
         ["Which word best describes Lucia?", "creative", ["selfish", "shy", "careless"], "elements", "She thought of a new solution."]] },
  // ---------------- informational, grades 4-5 ----------------
  { id: "I4a", skill: "INF", g: "45", title: "Coral Reefs Under Threat", text: "Coral reefs look like colorful rocks, but they are made of tiny animals called coral polyps. Reefs cover less than one percent of the ocean floor, yet about a quarter of all ocean species depend on them for food and shelter. Florida has the only coral reef in the continental United States. Today, reefs face serious threats. When ocean water gets too warm, coral polyps push out the algae that live inside them and give them color. The coral turns white, which is called bleaching. If the water stays warm too long, the coral can die. Scientists are now growing coral in underwater nurseries and replanting it on damaged reefs.",
    qs: [["What is the central idea?", "coral reefs are important and threatened, and people are working to help", ["coral is a kind of rock", "Florida is warm", "algae are colorful"], "central", "The details cover why reefs matter, the threat and the help."],
         ["What are coral reefs made of?", "tiny animals called coral polyps", ["colorful rocks", "sand", "only plants"], "central", "They are made of tiny animals called coral polyps."],
         ["What causes bleaching?", "ocean water that is too warm", ["too many fish", "boats", "cold water"], "structure", "When water gets too warm, the coral turns white."],
         ["In the second sentence, the word \"yet\" shows", "a contrast between reefs' small size and big importance", ["the order of events", "an example", "a question"], "structure", "Reefs are small, yet many species depend on them."],
         ["Why does the author mention underwater nurseries?", "to show a way scientists are helping reefs", ["to describe a school", "to explain bleaching", "to list fish"], "purpose", "Nurseries grow coral to replant damaged reefs."]] },
  { id: "I4b", skill: "INF", g: "45", title: "How the Bicycle Changed", text: "The first bicycles, built in the early 1800s, had no pedals. Riders pushed along the ground with their feet. Later, inventors added pedals to the front wheel. To go faster, they made the front wheel huge, and some were taller than a person! These \"high-wheelers\" were fast but dangerous, because riders could tip forward and fall. In the 1880s, the \"safety bicycle\" was invented. It had two wheels of the same size and a chain that connected the pedals to the back wheel. This design worked so well that bicycles today still look much the same.",
    qs: [["How is this text organized?", "in time order", ["as a list of rules", "comparing two animals", "as questions and answers"], "structure", "It moves from the early 1800s to the 1880s to today."],
         ["Why were high-wheelers dangerous?", "riders could tip forward and fall", ["they had no seats", "they were too slow", "they had no wheels"], "structure", "Riders could tip forward and fall."],
         ["What was new about the safety bicycle?", "same-size wheels and a chain to the back wheel", ["no pedals", "a huge front wheel", "three wheels"], "central", "It had same-size wheels and a chain."],
         ["What is the central idea?", "bicycles changed over time to become safer and better", ["bicycles were invented recently", "high-wheelers are best", "chains break easily"], "central", "The text traces improvements over time."],
         ["What is the author's purpose?", "to explain how bicycles developed", ["to persuade readers to ride", "to tell a made-up story", "to sell bikes"], "purpose", "It explains the history of the bicycle."]] },
  { id: "I4c", skill: "INF", g: "45", title: "Kids Need Recess", text: "Every elementary school should give students at least 30 minutes of recess each day. Research shows that children who get a break during the school day pay better attention in class afterward. Recess also gives kids time to exercise, which keeps their bodies healthy. In addition, playing with others helps students learn to share, solve disagreements and make friends. Some people argue that recess takes time away from learning. However, students learn more when their brains get a chance to rest. Recess is not a break from learning; it is part of learning.",
    qs: [["What is the author's claim?", "schools should give at least 30 minutes of recess every day", ["recess takes time from learning", "exercise is boring", "kids should study more"], "argument", "The first sentence states the claim."],
         ["Which evidence supports the claim?", "children who get a break pay better attention afterward", ["some people dislike recess", "recess is outside", "schools have playgrounds"], "argument", "Research shows breaks help attention."],
         ["What opposing view does the author mention?", "recess takes time away from learning", ["recess is too long", "kids don't like recess", "playgrounds are unsafe"], "argument", "Some people argue that recess takes time away from learning."],
         ["\"Recess is not a break from learning; it is part of learning\" means", "recess helps kids learn too", ["recess should be cancelled", "learning is boring", "kids learn only at recess"], "figurative", "The author says recess supports learning."],
         ["What is the author's purpose?", "to persuade", ["to explain how to play tag", "to entertain with a story", "to describe a playground"], "purpose", "The author argues for more recess."]] },
  { id: "I4d", skill: "INF", g: "45", title: "Hurricane Season", text: "In Florida, hurricane season runs from June 1 to November 30. Hurricanes form over warm ocean water. Warm, wet air rises and cools, forming clouds and storms. As more air rushes in, the storm begins to spin. When its winds reach 74 miles per hour, the storm is called a hurricane. Forecasters use satellites and special airplanes called \"hurricane hunters\" to track storms. Families prepare by making a plan, storing water and food, and knowing their evacuation route.",
    qs: [["When is hurricane season in Florida?", "June 1 to November 30", ["January to March", "all year", "only in August"], "central", "The first sentence gives the dates."],
         ["Where do hurricanes form?", "over warm ocean water", ["over mountains", "in cold lakes", "in deserts"], "central", "Hurricanes form over warm ocean water."],
         ["When is a storm called a hurricane?", "when its winds reach 74 miles per hour", ["when it rains", "when it spins at all", "when it reaches land"], "structure", "At 74 miles per hour it is called a hurricane."],
         ["What are \"hurricane hunters\"?", "special airplanes that track storms", ["people who chase storms in cars", "satellites", "weather maps"], "context", "They are special airplanes."],
         ["Why does the author include the last sentence?", "to show how families can get ready", ["to describe clouds", "to explain satellites", "to give the dates"], "purpose", "It lists ways families prepare."]] },
  // ---------------- across genres, grades 3-5 ----------------
  { id: "G3a", skill: "AG", g: "3", title: "Two Texts About Owls", text: "Text A: Owls are birds of prey that hunt mostly at night. Their large eyes help them see in the dark, and soft feathers let them fly almost silently.\nText B: The owl glides like a whisper through the night,\nA shadow with eyes of golden light.",
    qs: [["How are Text A and Text B alike?", "both describe owls moving quietly at night", ["both give facts about eggs", "both are poems", "both are about the daytime"], "compare", "Both show owls flying quietly at night."],
         ["How are the two texts different?", "Text A gives facts; Text B uses figurative language", ["Text A is a poem", "both use rhyme", "neither mentions night"], "compare", "Text A informs; Text B describes with comparisons."],
         ["\"Glides like a whisper\" means the owl", "flies very quietly", ["makes loud noises", "talks to others", "walks slowly"], "figurative", "A whisper is quiet, so the owl flies quietly."],
         ["Which is the best summary of Text A?", "Owls hunt at night and have features that help them see and fly quietly", ["Owls are birds", "Owls have eyes", "Owls sleep at night"], "summary", "A summary keeps the most important ideas."],
         ["\"A shadow with eyes of golden light\" is an example of", "a metaphor", ["a fact", "a question", "a list"], "figurative", "It says the owl is a shadow without using like or as."]] },
  { id: "G3b", skill: "AG", g: "3", title: "The Lighthouse", text: "The storm roared like a hungry lion, throwing waves against the rocks. Inside the lighthouse, Nora climbed the spiral stairs two at a time. The great lamp had flickered out, and somewhere in the dark a fishing boat was trying to find the harbor. Her fingers were ice, but she struck a match, then another, until the wick caught. Light swept across the black water. Far below, a horn sounded twice: the boat had seen it. Nora sank onto the top step, her heart pounding like a drum.",
    qs: [["\"The storm roared like a hungry lion\" shows that the storm was", "loud and fierce", ["quiet", "a real lion", "far away"], "figurative", "A simile compares the storm to a roaring lion."],
         ["\"Her fingers were ice\" means", "her fingers were very cold", ["her fingers were made of ice", "she held ice", "she was skating"], "figurative", "It is a metaphor for very cold fingers."],
         ["Which is the best summary?", "During a storm, Nora relights the lighthouse lamp so a boat can find the harbor", ["Nora climbs stairs", "A boat sounds its horn", "Nora likes storms"], "summary", "It includes the problem and how Nora solved it."],
         ["Why did the horn sound twice?", "the boat had seen the light", ["the boat was sinking", "Nora rang it", "the storm stopped"], "summary", "The text says the boat had seen it."],
         ["\"Her heart pounding like a drum\" shows Nora felt", "excited and worn out after the danger", ["bored", "sleepy", "angry"], "figurative", "Her heart beat hard after the rush."]] },
  { id: "G3c", skill: "AG", g: "3", title: "Why Sleep Matters", text: "Doctors recommend that children ages 6 to 12 get 9 to 12 hours of sleep each night. During sleep, the brain sorts and stores what you learned during the day. Without enough sleep, it is harder to pay attention, remember information and control emotions. Screens can make it harder to fall asleep because their bright light tells the brain it is still daytime.",
    qs: [["Which best paraphrases \"the brain sorts and stores what you learned\"?", "the brain organizes and keeps new learning", ["the brain forgets everything", "the brain grows bigger", "the brain stops working"], "summary", "Sorts and stores means organizes and keeps."],
         ["Which is the best summary?", "Kids need 9 to 12 hours of sleep to help their brains, and screens can make sleep harder", ["Screens are bright", "Doctors like sleep", "Kids are 6 to 12"], "summary", "It keeps the key ideas from the whole text."],
         ["Why can screens make it harder to fall asleep?", "their light tells the brain it is still daytime", ["they are loud", "they are cold", "they are heavy"], "summary", "The bright light tells the brain it is daytime."],
         ["Which best paraphrases \"Without enough sleep, it is harder to pay attention\"?", "When you don't sleep enough, it is harder to focus", ["Sleep makes you lose attention", "Paying attention needs no sleep", "Attention makes you sleepy"], "summary", "Paying attention means focusing."],
         ["What is the author's purpose?", "to inform readers about why sleep matters", ["to tell a bedtime story", "to sell screens", "to describe dreams"], "summary", "It gives facts about sleep."]] },
  { id: "G3d", skill: "AG", g: "3", title: "Two Accounts of the Moon Landing", text: "Account A: On July 20, 1969, astronauts Neil Armstrong and Buzz Aldrin landed on the Moon. Armstrong stepped out first and said, \"That's one small step for man, one giant leap for mankind.\"\nAccount B: Dad woke us up and we crowded around the TV. The picture was fuzzy, but when the astronaut stepped onto the Moon, Mom cried and Dad cheered so loud the neighbors knocked on the wall!",
    qs: [["How are the two accounts different?", "Account A gives facts; Account B shows how a family felt", ["both are about the same family", "both are made up", "both give the date"], "compare", "A reports facts; B tells one family's experience."],
         ["Which detail is in both accounts?", "an astronaut stepped onto the Moon", ["the TV picture was fuzzy", "the date July 20, 1969", "Mom cried"], "compare", "Both describe the step onto the Moon."],
         ["Who is telling Account B?", "someone in the family who watched it", ["a news reporter", "the astronaut", "a narrator outside the story"], "compare", "The narrator says \"us\" and \"Dad\" and \"Mom.\""],
         ["\"One giant leap for mankind\" means", "a huge step forward for all people", ["a very long jump", "a mistake", "a dance"], "figurative", "It was a big moment for everyone, not a real jump."],
         ["Which is the best summary of Account B?", "A family excitedly watched the Moon landing on TV", ["The Moon is far away", "The neighbors were angry", "TVs were fuzzy"], "summary", "It keeps the main event and feeling."]] }
];
// ---------------- Learn it: short lessons by skill and level group ----------------
const SH_READ_LESSONS = {
  PA: { k1: { title: "Hear the sounds in words", steps: ["Say the word slowly.", "Stretch it like a rubber band: s-u-n.", "Hold up one finger for each sound you hear."] },
        2: { title: "Play with sounds", steps: ["Say the word slowly and hear every sound.", "Take one sound away, or swap it for a new one.", "Say the new word. Is it a real word?"] } },
  PH: { k1: { title: "Sound it out", steps: ["Look at each letter from left to right.", "Say the sound each letter makes.", "Blend the sounds together faster and faster until you hear the word."] },
        2: { title: "Vowel teams and bossy r", steps: ["Look for two vowels together, like ai, ee or oa: they often make one long sound (rain, feet, boat).", "An r after a vowel changes the sound: car, corn, bird.", "Read the word, then check that it sounds like a real word."] },
        3: { title: "Read long words", steps: ["Cover any prefix (un-, re-) and suffix (-ful, -ly).", "Split the rest into syllables: each syllable has one vowel sound.", "Read each part, then put the whole word together."] } },
  HFW: { k1: { title: "Words we see a lot", steps: ["Look at the whole word.", "Say it, spell it, say it again.", "Find the tricky part and remember it."] },
         2: { title: "Snap words in sentences", steps: ["Read the whole sentence.", "Try each word in the blank.", "Pick the word that makes sense and is spelled right."] } },
  VOC: { k1: { title: "What words mean", steps: ["Opposites mean very different things: hot and cold.", "Some words mean almost the same thing: happy and glad.", "Groups: an apple and a pear are both fruits."] },
         2: { title: "Prefixes, suffixes and clues", steps: ["Find the base word.", "Add the meaning of the prefix or suffix: un- means not, -ful means full of.", "Use the other words in the sentence as clues."] },
         4: { title: "Roots and context", steps: ["Look for a Greek or Latin root: port means carry, spect means look.", "Use the prefix and suffix too.", "Check that your meaning makes sense in the sentence."] } },
  LIT: { k1: { title: "Story parts", steps: ["Who is in the story? Those are the characters.", "Where does it happen? That is the setting.", "What is the problem, and how is it solved?"],
               example: { text: "Sam lost his hat at the park. He looked under the slide. He found it!", q: "What was Sam's problem?", a: "He lost his hat.", think: "The story starts with something going wrong: Sam lost his hat. That is the problem." } },
         2: { title: "Characters and lessons", steps: ["Notice what the main character says, does and feels.", "Find the problem and how the character deals with it.", "Ask: what lesson could anyone learn from this?"],
              example: { text: "Tia wanted to win the spelling bee. She studied every night. She missed a word, but she smiled and said, \"I'll try again next year.\"", q: "What lesson does the story teach?", a: "Keep trying even when you don't win.", think: "Tia did not win, but she plans to try again. The lesson is about not giving up." } },
         45: { title: "Theme and point of view", steps: ["Track how the main character changes from beginning to end.", "Notice who is telling the story: a character (I, we) or a narrator outside it (he, she).", "State the theme as a full sentence, and back it up with two details."],
               example: { text: "I told everyone I hated the new kid. Then he shared his lunch with me when I forgot mine. I guess I was wrong about him.", q: "What is the theme?", a: "First impressions can be wrong.", think: "The narrator changes his mind after the new kid is kind. Two details: he said he hated him, then he admits he was wrong." } } },
  INF: { k1: { title: "Learn facts", steps: ["Look at the title: what is the topic?", "Listen for facts about the topic.", "Tell what the text is mostly about."],
               example: { text: "Bats sleep in the day. They fly at night. They eat bugs.", q: "What is this mostly about?", a: "bats", think: "Every sentence tells about bats, so it is mostly about bats." } },
         2: { title: "Main idea and details", steps: ["Read the title and the first sentence.", "Find details that all tell more about one big idea.", "Say the main idea in your own words."],
              example: { text: "Owls are good hunters. They see well at night. They fly without a sound. Their claws are sharp.", q: "What is the main idea?", a: "Owls are good hunters.", think: "Night vision, quiet flying and sharp claws all show why owls are good hunters." } },
         45: { title: "Central idea, structure and purpose", steps: ["Find the central idea that most details support.", "Notice how it is organized: time order, cause and effect, problem and solution, or claim and reasons.", "Ask why the author wrote it: to inform, to explain or to persuade."],
               example: { text: "Plastic straws harm sea turtles. Turtles mistake them for food. Our cafeteria should switch to paper straws.", q: "What is the author's purpose?", a: "to persuade", think: "The author gives a reason and says what we should do. That is persuading." } } },
  AG: { 3: { title: "Figurative language and summaries", steps: ["A simile compares two things using like or as. A metaphor says one thing is another.", "Ask what the comparison really means.", "A summary tells only the most important ideas, in your own words."],
             example: { text: "The classroom was a beehive before the field trip.", q: "What does this metaphor mean?", a: "The classroom was busy and buzzing with noise.", think: "A beehive is busy and buzzing, so the classroom was full of busy, noisy students." } } }
};
if (typeof module !== "undefined") module.exports = Object.assign(module.exports || {}, { SH_PASSAGES, SH_READ_LESSONS });
